mapper.select:
SELECT s.id, s.student_id AS studentId, s.course_id AS courseId, c.course_name AS courseName, s.score, s.semester, s.exam_name AS examName, s.exam_time AS examTime FROM score s INNER JOIN course c ON s.course_id = c.id WHERE s.student_id = #{studentId}
AND s.course_id = #{courseId}
ORDER BY s.exam_time ASC, s.create_time ASC
